  // After final glyph lands (delay + duration), trigger settle and underline
  const finalGlyphDelay = (maxGlyphIndex * staggerMs + glyphDuration) / 1000;
  const underlineStartTime = finalGlyphDelay + 0.12; // 120ms after final glyph

  settleTl.play(finalGlyphDelay);
  underlineTl.play(underlineStartTime);
  subheadTl.play(finalGlyphDelay + 0.05); // Slight overlap with settle

  // ============================================================================
  // 11. APPLY CINEMATIC PRIMITIVES
