// HELPER: Create gradient texture for backdrop
// ============================================================================
function createGradientTexture(THREE) {
  const canvas = document.createElement('canvas');
  canvas.width = 512;
  canvas.height = 512;

  const ctx = canvas.getContext('2d');
  if (!ctx) return new THREE.CanvasTexture(canvas);

  // Vertical gradient: #0b0b10 (top) to #13131a (bottom)
  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0, '#0b0b10');
  gradient.addColorStop(1, '#13131a');

  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Add 1.5% mono grain (subtle noise)
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;
  for (let i = 0; i < data.length; i += 4) {
    const noise = (Math.random() - 0.5) * 2 * 0.015 * 255;
    data[i] += noise;
    data[i + 1] += noise;
    data[i + 2] += noise;
  }
  ctx.putImageData(imageData, 0, 0);

  const texture = new THREE.CanvasTexture(canvas);
  texture.magFilter = THREE.LinearFilter;
  texture.minFilter = THREE.LinearFilter;
  return texture;
}

// ============================================================================
// HELPER: Fallback gradient for environments without canvas
// ============================================================================
function createFallbackGradient() {
  const canvas = new OffscreenCanvas(512, 512);
  const ctx = canvas.getContext('2d');
  if (!ctx) {
    // Return a simple solid color if neither Canvas nor OffscreenCanvas available
    return new (window.THREE || THREE.CanvasTexture)(new OffscreenCanvas(1, 1));
  }

  const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
  gradient.addColorStop(0, '#0b0b10');
  gradient.addColorStop(1, '#13131a');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  return new THREE.CanvasTexture(canvas.convertToBlob().then((blob) => {
    // Fallback: return a simple solid if async blob fails
    const solid = new OffscreenCanvas(1, 1);
    const solidCtx = solid.getContext('2d');
    if (solidCtx) {
      solidCtx.fillStyle = '#0b0b10';
      solidCtx.fillRect(0, 0, 1, 1);
    }
    return solid;
  }));
}
